function validate([prevRoom]) {
  if (!Array.isArray(prevRoom) || prevRoom.length < 2 || prevRoom.length > 100000) return 'prevRoom needs 2 to 10^5 values.';
  const n = prevRoom.length;
  if (prevRoom[0] !== -1) return 'prevRoom[0] must be -1.';
  const children = Array.from({ length: n }, () => []);
  for (let i = 1; i < n; i++) {
    const parent = prevRoom[i];
    if (!Number.isInteger(parent) || parent < 0 || parent >= n) return 'Every other prevRoom[i] is a room number from 0 to n - 1.';
    children[parent].push(i);
  }
  const queue = [0];
  for (let k = 0; k < queue.length; k++) for (const child of children[queue[k]]) queue.push(child);
  if (queue.length !== n) return 'Every room must be reachable from room 0 (no cycles).';
  return null;
}

