function waysToBuildRooms(prevRoom) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent & 1n) result = (result * base) % MOD;
      base = (base * base) % MOD;
      exponent >>= 1n;
    }
    return result;
  };

  const n = prevRoom.length;
  const children = Array.from({ length: n }, () => []);
  for (let room = 1; room < n; room++) {
    children[prevRoom[room]].push(room);
  }

  const order = [0];
  for (let k = 0; k < order.length; k++) {
    for (const child of children[order[k]]) order.push(child);
  }

  const size = new Array(n).fill(1);
  let sizeProduct = 1n;
  let factorial = 1n;
  for (let k = n - 1; k >= 0; k--) {
    const room = order[k];
    if (room !== 0) size[prevRoom[room]] += size[room];
    sizeProduct = (sizeProduct * BigInt(size[room])) % MOD;
    factorial = (factorial * BigInt(k + 1)) % MOD;
  }
  return Number((factorial * power(sizeProduct, MOD - 2n)) % MOD);
}

