function waysToBuildRooms(prevRoom) {
  // Count build orders directly: memoise on the set of rooms already built.
  const n = prevRoom.length;
  const full = (1 << n) - 1;
  const memo = new Map();
  const count = (built) => {
    if (built === full) return 1;
    if (memo.has(built)) return memo.get(built);
    let total = 0;
    for (let room = 1; room < n; room++) {
      if (!(built & (1 << room)) && (built & (1 << prevRoom[room]))) total = (total + count(built | (1 << room))) % 1000000007;
    }
    memo.set(built, total);
    return total;
  };
  return count(1);
}

