function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? pick(1500, 2000) : pick(2, 9);
  const labels = Array.from({ length: n - 1 }, (_, i) => i + 1);
  for (let i = labels.length - 1; i > 0; i--) {
    const j = pick(0, i);
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const order = [0, ...labels];
  const shape = pick(0, 4);
  const prevRoom = new Array(n).fill(-1);
  for (let k = 1; k < n; k++) {
    let parentIndex;
    if (shape === 0) parentIndex = k - 1;
    else if (shape === 1) parentIndex = 0;
    else if (shape === 2) parentIndex = pick(Math.max(0, k - 3), k - 1);
    else if (shape === 3) parentIndex = Math.floor((k - 1) / 2);
    else parentIndex = pick(0, k - 1);
    prevRoom[order[k]] = order[parentIndex];
  }
  return [prevRoom];
}
